export interface Product {
  name: string;
  sku: string;
  description?: string;
  image?: string;
  url?: string;
  specs?: { label: string; value: string }[];
  datasheets?: { name: string; url: string; size?: string }[];
  standards?: string[];
}

export interface ProductCategory {
  slug: string;
  /** Короткий title для nav, breadcrumbs, карточек на /catalog. */
  title: string;
  /**
   * Опциональный длинный H1 / meta-title для SEO. Если задан — используется
   * на странице категории как H1 и в начале meta-title, иначе fallback на `title`.
   * Применяется, когда основной title слишком короткий для SEO, но менять его
   * во всём UI нежелательно (раздуло бы breadcrumbs и nav).
   */
  seoH1?: string;
  /**
   * Опциональный meta-title (тег <title>) для SEO. Если задан — используется
   * как есть, иначе fallback-шаблон в generateMetadata. Позволяет задать
   * точный, не пере-оптимизированный заголовок ≤ 60 символов под целевой
   * запрос конкретной категории.
   */
  metaTitle?: string;
  description: string;
  image: string;
  /** Visual grouping — e.g. 'consumables' (default), 'furniture'. */
  group?: 'consumables' | 'furniture';
  products: Product[];
}

